package study.apps;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class DomainTests{static class Fake implements Store {Map<String,Item> rows=new HashMap<>();public void ready(){}public Item create(String id,String label){if(rows.containsKey(id))throw new Problem(409,"duplicate");Item r=new Item(id,label,null);rows.put(id,r);return r;}public Item get(String id){return rows.get(id);}public Item change(String id,String h,boolean back){Item r=rows.get(id);if(r==null)throw new Problem(404,"missing");if(back?!h.equals(r.holder()):r.holder()!=null)throw new Problem(409,"conflict");Item n=new Item(id,r.label(),back?null:h);rows.put(id,n);return n;}}
 @Test void businessBoundariesAndConflicts(){Domain d=new Domain(new Fake());d.create(new ItemInput("a","Camera"));assertEquals("person",d.change("a",new HolderInput("person"),false).holder());assertThrows(Problem.class,()->d.change("a",new HolderInput("other"),false));assertThrows(Problem.class,()->d.change("a",new HolderInput("other"),true));assertNull(d.change("a",new HolderInput("person"),true).holder());assertThrows(Problem.class,()->Rules.authorize(null,"synthetic-unit-token"));Rules.authorize("Bearer synthetic-unit-token","synthetic-unit-token");}
}
